 "content": "def transform(grid):
    H,W=len(grid),len(grid[0])
    rg=[]; cg=[]; s=0
    for r in range(H+1):
        if r==H or len(set(grid[r]))==1:
            if r>s: rg.append((s,r))
            s=r+1
    s=0
    for c in range(W+1):
        if c==W or len({grid[r][c] for r in range(H)})==1:
            if c>s: cg.append((s,c))
            s=c+1
    # Cells encode count of the exceptional color. One occurrence maps to 3;
    # two or more map to 1, and empty maps to 0.
    out=[]
    for a,b in rg:
        row=[]
        for x,y in cg:
            color_counts={}
            for r in range(a,b):
                for c in range(x,y):
                    v=grid[r][c]
                    color_counts[v]=color_counts.get(v,0)+1
            base=max(color_counts,key=color_counts.get)
            exceptional=[v for v,n in color_counts.items() if v!=base]
            n=sum(color_counts[v] for v in exceptional)
            row.append(3 if n==1 else (1 if n>=2 else 0))
        out.append(row)
    return out
