 "content": "def transform(grid):
    H, W = len(grid), len(grid[0])
    row_groups, col_groups = [], []
    start = 0
    for r in range(H + 1):
        if r == H or len(set(grid[r])) == 1:
            if r > start:
                row_groups.append((start, r))
            start = r + 1
    start = 0
    for c in range(W + 1):
        if c == W or len({grid[r][c] for r in range(H)}) == 1:
            if c > start:
                col_groups.append((start, c))
            start = c + 1
    out = []
    for r0, r1 in row_groups:
        row = []
        for c0, c1 in col_groups:
            counts = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    counts[v] = counts.get(v, 0) + 1
            background = max(counts, key=counts.get)
            marks = sum(n for color, n in counts.items() if color != background)
            row.append(0 if marks == 0 else (3 if marks == 1 else 1))
        out.append(row)
    return out
